  padding: 18px 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(31,35,48,0.82) 0%, rgba(19,22,31,0.92) 100%);
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
  text-align: left;
}

.spm-opt:hover {
  transform: translateY(-1px);
  border-color: var(--line-3);
}

.spm-opt.on {
  border-color: rgba(200,255,0,0.34);
  background: linear-gradient(180deg, rgba(200,255,0,0.15) 0%, rgba(26,31,18,0.94) 100%);
  box-shadow: 0 12px 24px rgba(200,255,0,0.09);
}

.spm-opt h4 {
  font-family: 'Outfit', 'Pretendard', sans-serif;
  font-size: 15px;
  font-weight: 800;
  margin-bottom: 6px;
  color: var(--text);
}

.spm-opt.on h4 {
  color: var(--accent-2);
}

.spm-opt p {
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-2);
}

.spm-sl-stack {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.spm-sl-meta {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 12px;
}

.spm-sl-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-2);
}

.spm-sl-val {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  font-size: 15px;
  color: var(--accent);
}

.spm-range {
  -webkit-appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 999px;
  outline: none;
  background: linear-gradient(90deg, rgba(255,255,255,0.08) 0%, rgba(255,255,255,0.18) 100%);
  cursor: pointer;
}

.spm-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 2px solid #10120E;
  background: var(--accent);
  box-shadow: 0 0 0 4px rgba(200,255,0,0.14);
  transition: transform 0.14s ease;
}

.spm-range::-webkit-slider-thumb:hover {
  transform: scale(1.08);
}

.spm-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.spm-pill {
  padding: 10px 16px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.04);
  color: var(--text-2);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, color 0.18s ease;
}

.spm-pill:hover {
  transform: translateY(-1px);
  border-color: var(--line-3);
  color: var(--text);
}

.spm-pill.on {
  color: #0B0D0A;
  border-color: transparent;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%);
  box-shadow: 0 10px 24px rgba(200,255,0,0.14);
}

.spm-set-big {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  margin-bottom: 22px;
}

.spm-set-n {
  font-family: 'Outfit', sans-serif;
  font-weight: 800;
  font-size: clamp(84px, 20vw, 100px);
  line-height: 0.88;
  letter-spacing: -0.02em;
}

.spm-set-unit {
  font-family: 'Outfit', sans-serif;
  padding-bottom: 12px;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-2);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.spm-sum-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.spm-sum-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 14px;
  background: rgba(255,255,255,0.03);
}

.spm-sum-k {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-2);
}

.spm-sum-v,
.spm-sum-va {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.04em;
}

.spm-sum-v {
  color: var(--text);
}

.spm-sum-va {
  color: var(--accent);
}

.spm-foot {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 30;
  width: min(calc(100% - 24px), 492px);
  transform: translateX(-50%);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(12, 14, 20, 0.82);
  backdrop-filter: blur(18px);
  box-shadow: var(--shadow);
}

.spm-btn-back,
.spm-btn-next,
.spm-btn-cta,
.spm-g-quit {
  border: none;
  cursor: pointer;
}

.spm-btn-back {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px;
  color: var(--text-2);
  background: transparent;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: color 0.18s ease, transform 0.18s ease;
}

.spm-btn-back:hover {
  color: var(--text);
  transform: translateX(-1px);
}

.spm-btn-next {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border-radius: 16px;
  color: #0B0D0A;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
  box-shadow: 0 12px 24px rgba(200,255,0,0.14);
}

.spm-btn-next:hover {
  transform: translateY(-1px);
}

.spm-btn-next:active,
.spm-btn-cta:active {
  transform: scale(0.98);
}

.spm-btn-next:disabled {
  background: rgba(255,255,255,0.06);
  color: var(--text-3);
  box-shadow: none;
  cursor: not-allowed;
}

.spm-game {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
  transition: background 0.12s ease, background-image 0.12s ease;
}

.spm-g-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at center, transparent 35%, rgba(0,0,0,0.12) 70%, rgba(0,0,0,0.26) 100%),
    linear-gradient(180deg, rgba(255,255,255,0.04), transparent 20%);
}

.spm-g-grid {
  position: absolute;
  inset: 0;
  opacity: 0.2;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255,255,255,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.04) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: radial-gradient(circle at center, black 25%, transparent 82%);
}

.spm-g-hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px;
  pointer-events: none;
}

.spm-hud-pill,
.spm-hud-time {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 18px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.10);
  background: rgba(6,7,10,0.26);
  backdrop-filter: blur(14px);
  color: rgba(255,255,255,0.85);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.spm-hud-pill {
  font-size: 13px;
}

.spm-hud-time {
  font-size: 20px;
  font-weight: 800;
}

.spm-g-stage {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 320px;
  min-height: 320px;
  padding: 24px;
}

.spm-g-stage::before {
  content: '';
  position: absolute;
  width: min(64vw, 420px);
  height: min(64vw, 420px);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,0.10), transparent 64%);
  filter: blur(8px);
}

.spm-s-arr-shell {
  display: flex;
  align-items: center;
  justify-content: center;
  width: min(54vw, 320px);
  height: min(54vw, 320px);
}

.spm-s-arr {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 12px 28px rgba(0,0,0,0.18));
}

.spm-s-num {
  font-family: 'Outfit', sans-serif;
  font-size: clamp(140px, 28vw, 280px);
  font-weight: 900;
  line-height: 0.88;
  letter-spacing: -0.02em;
  color: rgba(255,255,255,0.95);
  text-shadow: 0 14px 26px rgba(0,0,0,0.18);
}

.spm-g-hint {
  position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  font-family: 'Outfit', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.3);
  white-space: nowrap;
  pointer-events: none;
}

.spm-g-quit {
  position: absolute;
  right: 22px;
  bottom: 22px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.10);
  background: rgba(6,7,10,0.28);
  backdrop-filter: blur(12px);
  color: rgba(255,255,255,0.62);
  font-family: 'Outfit', sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: border-color 0.18s ease, color 0.18s ease;
}

.spm-g-quit:hover {
  color: rgba(255,255,255,0.92);
  border-color: rgba(255,255,255,0.18);
}

/* ── 인트로 ─────────────────────────────────────────────── */

.spm-intro {
  min-height: 100vh;
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
  padding: 48px 20px 40px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.spm-intro-top {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.spm-intro-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  border-radius: 999px;
  border: 1px solid rgba(200,255,0,0.16);
  background: rgba(200,255,0,0.08);
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  width: fit-content;
  margin-bottom: 8px;
}

.spm-intro-title {
  font-family: 'Outfit', 'Pretendard', sans-serif;
  font-weight: 900;
  font-size: clamp(52px, 14vw, 72px);
  line-height: 0.92;
  letter-spacing: -0.03em;
}

.spm-intro-sub {
  margin-top: 14px;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-2);
}

.spm-intro-cards {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.spm-intro-btn {
  position: relative;
  overflow: hidden;
  width: 100%;
  padding: 28px 24px;
  border: 1px solid var(--line);
  border-radius: 26px;
  cursor: pointer;
  text-align: left;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.spm-intro-btn:hover {
  transform: translateY(-2px);
}

.spm-intro-btn.create {
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%);
  border-color: transparent;
  box-shadow: 0 16px 32px rgba(200,255,0,0.18);
}

.spm-intro-btn.fav {
  background: linear-gradient(180deg, rgba(24, 27, 38, 0.94) 0%, rgba(14, 16, 24, 0.94) 100%);
  box-shadow: var(--shadow);
}

.spm-intro-btn-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  margin-bottom: 10px;
}

.spm-intro-btn.create .spm-intro-btn-num {
  color: rgba(11,13,10,0.5);
}

.spm-intro-btn.fav .spm-intro-btn-num {
  color: var(--text-3);
}

.spm-intro-btn-title {
  font-family: 'Outfit', 'Pretendard', sans-serif;
  font-weight: 900;
  font-size: 28px;
  line-height: 1;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.spm-intro-btn.create .spm-intro-btn-title {
  color: #0B0D0A;
}

.spm-intro-btn.fav .spm-intro-btn-title {
  color: var(--text);
}

.spm-intro-btn-desc {
  font-size: 13px;
  font-weight: 500;
  line-height: 1.5;
}

.spm-intro-btn.create .spm-intro-btn-desc {
  color: rgba(11,13,10,0.62);
}

.spm-intro-btn.fav .spm-intro-btn-desc {
  color: var(--text-2);
}

/* ── 즐겨찾기 목록 ──────────────────────────────────────── */

.spm-favlist {
  min-height: 100vh;
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
  padding: 32px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.spm-favlist-head {
  display: flex;
  align-items: center;
  gap: 14px;
}

.spm-favlist-back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.04);
  color: var(--text-2);
  cursor: pointer;
  transition: border-color 0.18s ease, color 0.18s ease;
}

.spm-favlist-back:hover {
  border-color: var(--line-3);
  color: var(--text);
}

.spm-favlist-title {
  font-family: 'Outfit', 'Pretendard', sans-serif;
  font-weight: 900;
  font-size: 24px;
  letter-spacing: -0.02em;
}

.spm-favlist-count {
  margin-left: auto;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-3);
  letter-spacing: 0.08em;
}

.spm-fav-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 48px 0;
}

.spm-fav-empty-ico {
  font-size: 48px;
  opacity: 0.18;
}

.spm-fav-empty-txt {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-3);
  text-align: center;
  line-height: 1.6;
}

.spm-fav-list-inner {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.spm-fav-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 16px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(20,23,33,0.94) 0%, rgba(13,15,23,0.94) 100%);
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
  text-align: left;
}

.spm-fav-item:hover {
  transform: translateY(-1px);
  border-color: rgba(200,255,0,0.2);
  box-shadow: 0 12px 24px rgba(200,255,0,0.06);
}

.spm-fav-item-body {
  flex: 1;
  min-width: 0;
}

.spm-fav-label {
  font-family: 'Outfit', 'Pretendard', sans-serif;
  font-weight: 800;
  font-size: 15px;
  color: var(--text);
  margin-bottom: 5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.spm-fav-meta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-3);
  letter-spacing: 0.06em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.spm-fav-del {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.07);
  background: transparent;
  color: var(--text-3);
  cursor: pointer;
  transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease;
}

.spm-fav-del:hover {
  border-color: rgba(255, 80, 80, 0.4);
  color: rgba(255, 80, 80, 0.8);
  background: rgba(255, 80, 80, 0.06);
}

.spm-fav-loading {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.spm-fav-skel {
  height: 76px;
  border-radius: 20px;
  background: rgba(255,255,255,0.04);
  animation: spm-skel-pulse 1.4s ease-in-out infinite;
}

@keyframes spm-skel-pulse {
  0%, 100% { opacity: 0.5; }
  50%       { opacity: 1; }
}

/* ── 저장 모달 ──────────────────────────────────────────── */

.spm-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(4,5,9,0.72);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0 12px 24px;
  animation: spm-backdrop-in 0.2s ease both;
}

@keyframes spm-backdrop-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.spm-modal {
  width: 100%;
  max-width: 492px;
  padding: 28px 24px 24px;
  border: 1px solid var(--line-2);
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(22,25,36,0.98) 0%, rgba(13,15,22,0.98) 100%);
  box-shadow: 0 -4px 40px rgba(0,0,0,0.4);
  animation: spm-modal-up 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes spm-modal-up {
  from { transform: translateY(32px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.spm-modal-title {
  font-family: 'Outfit', 'Pretendard', sans-serif;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.spm-modal-sub {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-2);
  margin-bottom: 20px;
  line-height: 1.5;
}

.spm-modal-input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--line-2);
  border-radius: 14px;
  background: rgba(255,255,255,0.05);
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
  outline: none;
  margin-bottom: 16px;
  transition: border-color 0.18s ease;
}

.spm-modal-input:focus {
  border-color: var(--accent-line);
}

.spm-modal-input::placeholder {
  color: var(--text-3);
  font-weight: 500;
}

.spm-modal-row {
  display: flex;
  gap: 10px;
}

.spm-modal-cancel {
  flex: 1;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255,255,255,0.04);
  color: var(--text-2);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: border-color 0.18s ease, color 0.18s ease;
}

.spm-modal-cancel:hover {
  border-color: var(--line-3);
  color: var(--text);
}

.spm-modal-save {
  flex: 2;
  padding: 14px;
  border: none;
  border-radius: 14px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%);
  color: #0B0D0A;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  box-shadow: 0 10px 20px rgba(200,255,0,0.14);
}

.spm-modal-save:hover {
  transform: translateY(-1px);
}

.spm-modal-save:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

/* ── 4단계 풋터 별 버튼 ─────────────────────────────────── */

.spm-btn-star {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 16px;
  height: 48px;
  border-radius: 14px;
  border: 1px solid var(--line-2);
  background: rgba(255,255,255,0.04);
  color: var(--text-3);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease, transform 0.18s ease;
  white-space: nowrap;
}

.spm-btn-star:hover {
  border-color: rgba(200,255,0,0.3);
  color: var(--accent);
  background: rgba(200,255,0,0.06);
  transform: translateY(-1px);
}

